package com.nvv.mediadata.data.model.tmdbimport com.nvv.mediadata.data.utils.LocalDateSerializerimport kotlinx.serialization.SerialNameimport kotlinx.serialization.Serializableimport java.time.LocalDate@Serializabledata class MovieDetail(	@SerialName("adult")	override val adult: Boolean,	@SerialName("id")	override val id: Long,	@SerialName("backdrop_path")	override val background: String?,	@SerialName("poster_path")	override val poster: String?,	@SerialName("original_language")	override val originalLanguage: String,	@SerialName("genre_ids")	override val genres: List<Int>,	@SerialName("title")	override val title: String,	@SerialName("original_title")	override val originalTitle: String,	@SerialName("overview")	override val overview: String,	@SerialName("popularity")	override val popularity: Double,	@SerialName("release_date")	@Serializable(with = LocalDateSerializer::class)	override val releaseDate: LocalDate?,	@SerialName("vote_average")	override val voteAverage: Double,	@SerialName("vote_count")	override val voteCount: Int,	@SerialName("budget") val budget: Long = 0,	@SerialName("genres") val genresIds: List<Genre> = emptyList(),	@SerialName("homepage") val homepage: String? = null,	@SerialName("imdb_id") val imdb: String? = null,	@SerialName("origin_country") val originCountry: List<String> = emptyList(),	@SerialName("revenue") val revenue: Long = -1,	@SerialName("runtime") val runtime: Int = -1,	@SerialName("spoken_languages") val spokenLanguages: List<Language> = emptyList(),	@SerialName("status") val status: String = "",	@SerialName("tagline") val tagline: String = "",	@SerialName("production_countries")	val productionCountries: List<Language> = emptyList(),	@SerialName("production_companies")	val productionCompanies: List<Company> = emptyList(),	/// APPEND TO RESPONSE	@SerialName("release_dates")	val releaseDates: ReleaseDates = ReleaseDates(),	@SerialName("recommendations")	val recommendations: RecommendationMovieList = RecommendationMovieList(),	@SerialName("keywords")	val keywords: Keywords = Keywords(),	@SerialName("credits")	val credits: Credits = Credits(),	@SerialName("videos")	val videos: Videos = Videos(),	@SerialName("reviews")	val reviews: Reviews = Reviews(),	@SerialName("watch/providers")	val providers: WatchProviders = WatchProviders(),	@SerialName("images")	val images: Images = Images(),	@SerialName("external_ids")	val externalIds: ExternalIds = ExternalIds(),) : Media